def course_for_worker() -> list:
    """فرم فشردهٔ درس‌ها برای KV."""
    return [{"id": c["id"], "lv": c["level"], "t": c["title"], "b": c["body"], "x": c["tip"]} for c in COURSE]


def course_version() -> str:
    raw = json.dumps({"c": course_for_worker(), "l": LEVELS}, ensure_ascii=False, sort_keys=True)
    return hashlib.sha1(raw.encode("utf-8")).hexdigest()[:12]


def sync_course() -> bool:
    """درس‌ها را فقط در صورت تغییر به KV می‌نویسد. True = نوشته شد."""
    ver = course_version()
    if cloudflare_kv.get(COURSE_VER_KEY) == ver:
        return False
    payload = {"levels": LEVELS, "lessons": course_for_worker()}
    if cloudflare_kv.put(COURSE_KEY, payload) is False or cloudflare_kv.put(COURSE_VER_KEY, ver) is False:
        raise RuntimeError("learn course sync: KV write failed")
    print(f"[LEARN] course synced to KV ({len(COURSE)} lessons, v{ver})")
    return True
